CREATE TYPE "Role" AS ENUM ('CUSTOMER','OWNER','CHEF','ADMIN');
CREATE TYPE "OrderStatus" AS ENUM ('CREATED','AWAITING_CONFIRMATION','PREPARING','READY','COMPLETED','EXPIRED','CANCELLED');
CREATE TYPE "ImageKind" AS ENUM ('LOGO','BANNER','FOOD','CATEGORY');
CREATE TABLE "restaurants" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"public_id" TEXT NOT NULL,"name" VARCHAR(160) NOT NULL,"email" VARCHAR(254),"phone" VARCHAR(30) NOT NULL,"address" TEXT NOT NULL,"logo_url" TEXT,"banner_url" TEXT,"deleted_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "restaurants_pkey" PRIMARY KEY ("id"));
CREATE TABLE "users" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"restaurant_id" UUID,"email" VARCHAR(254) NOT NULL,"password_hash" TEXT NOT NULL,"full_name" TEXT NOT NULL,"role" "Role" NOT NULL,"deleted_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "users_pkey" PRIMARY KEY("id"));
CREATE TABLE "categories" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"restaurant_id" UUID NOT NULL,"name" TEXT NOT NULL,"image_url" TEXT,"position" INTEGER NOT NULL DEFAULT 0,"deleted_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "categories_pkey" PRIMARY KEY("id"));
CREATE TABLE "menu_items" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"restaurant_id" UUID NOT NULL,"category_id" UUID,"name" TEXT NOT NULL,"description" TEXT,"price" DECIMAL(12,2) NOT NULL,"dietary" TEXT,"image_url" TEXT,"available" BOOLEAN NOT NULL DEFAULT true,"preparation_minutes" INTEGER NOT NULL DEFAULT 15,"deleted_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "menu_items_pkey" PRIMARY KEY("id"));
CREATE TABLE "orders" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"public_id" TEXT NOT NULL,"restaurant_id" UUID NOT NULL,"customer_name" TEXT NOT NULL,"customer_phone" TEXT NOT NULL,"table_number" TEXT,"subtotal" DECIMAL(12,2) NOT NULL,"tax" DECIMAL(12,2) NOT NULL DEFAULT 0,"total" DECIMAL(12,2) NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'CREATED',"payment_verified" BOOLEAN NOT NULL DEFAULT false,"expires_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "orders_pkey" PRIMARY KEY("id"));
CREATE TABLE "order_items" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"order_id" UUID NOT NULL,"menu_item_id" UUID,"item_name" TEXT NOT NULL,"unit_price" DECIMAL(12,2) NOT NULL,"quantity" INTEGER NOT NULL,"notes" TEXT,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "order_items_pkey" PRIMARY KEY("id"));
CREATE TABLE "restaurant_settings" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"restaurant_id" UUID NOT NULL,"settings" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "restaurant_settings_pkey" PRIMARY KEY("id"));
CREATE TABLE "qr_mappings" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"restaurant_id" UUID NOT NULL,"public_code" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "qr_mappings_pkey" PRIMARY KEY("id"));
CREATE TABLE "sessions" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"user_id" UUID NOT NULL,"expires_at" TIMESTAMPTZ NOT NULL,"revoked_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "sessions_pkey" PRIMARY KEY("id")); CREATE TABLE "refresh_tokens" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"session_id" UUID NOT NULL,"token_hash" TEXT NOT NULL,"expires_at" TIMESTAMPTZ NOT NULL,"revoked_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "refresh_tokens_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "restaurants_public_id_key" ON "restaurants"("public_id"); CREATE UNIQUE INDEX "users_email_key" ON "users"("email"); CREATE UNIQUE INDEX "categories_restaurant_id_name_key" ON "categories"("restaurant_id","name"); CREATE UNIQUE INDEX "orders_public_id_key" ON "orders"("public_id"); CREATE UNIQUE INDEX "restaurant_settings_restaurant_id_key" ON "restaurant_settings"("restaurant_id"); CREATE UNIQUE INDEX "qr_mappings_restaurant_id_key" ON "qr_mappings"("restaurant_id"); CREATE UNIQUE INDEX "qr_mappings_public_code_key" ON "qr_mappings"("public_code"); CREATE UNIQUE INDEX "refresh_tokens_token_hash_key" ON "refresh_tokens"("token_hash"); CREATE INDEX "orders_restaurant_id_status_created_at_idx" ON "orders"("restaurant_id","status","created_at");
ALTER TABLE "users" ADD CONSTRAINT "users_restaurant_id_fkey" FOREIGN KEY("restaurant_id") REFERENCES "restaurants"("id"); ALTER TABLE "categories" ADD CONSTRAINT "categories_restaurant_id_fkey" FOREIGN KEY("restaurant_id") REFERENCES "restaurants"("id") ON DELETE CASCADE; ALTER TABLE "menu_items" ADD CONSTRAINT "menu_items_restaurant_id_fkey" FOREIGN KEY("restaurant_id") REFERENCES "restaurants"("id") ON DELETE CASCADE; ALTER TABLE "menu_items" ADD CONSTRAINT "menu_items_category_id_fkey" FOREIGN KEY("category_id") REFERENCES "categories"("id"); ALTER TABLE "orders" ADD CONSTRAINT "orders_restaurant_id_fkey" FOREIGN KEY("restaurant_id") REFERENCES "restaurants"("id") ON DELETE CASCADE; ALTER TABLE "order_items" ADD CONSTRAINT "order_items_order_id_fkey" FOREIGN KEY("order_id") REFERENCES "orders"("id") ON DELETE CASCADE; ALTER TABLE "order_items" ADD CONSTRAINT "order_items_menu_item_id_fkey" FOREIGN KEY("menu_item_id") REFERENCES "menu_items"("id"); ALTER TABLE "restaurant_settings" ADD CONSTRAINT "restaurant_settings_restaurant_id_fkey" FOREIGN KEY("restaurant_id") REFERENCES "restaurants"("id") ON DELETE CASCADE; ALTER TABLE "qr_mappings" ADD CONSTRAINT "qr_mappings_restaurant_id_fkey" FOREIGN KEY("restaurant_id") REFERENCES "restaurants"("id") ON DELETE CASCADE; ALTER TABLE "sessions" ADD CONSTRAINT "sessions_user_id_fkey" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE; ALTER TABLE "refresh_tokens" ADD CONSTRAINT "refresh_tokens_session_id_fkey" FOREIGN KEY("session_id") REFERENCES "sessions"("id") ON DELETE CASCADE;
